import frappe
from frappe import _
from frappe.model.document import Document


class CalendarDay(Document):
	"""One row per Jalali day. Generated by hozur.calendar_sync and kept in sync with
	Iran Holiday; nobody edits it by hand."""

	def on_trash(self):
		if not frappe.flags.in_uninstall:
			frappe.throw(_("Calendar days cannot be deleted"))
